/**
 * Payload: MessageSend.
 */
export const MessageSocketMessageSend = "socket_messageSend";

/**
 * Payload: ServerEvent.
 */
export const MessageSocketServerEvent = "socket_serverEvent";

/** ReceivedMessage is a decoded incoming message, typed by its name. */
export type ReceivedMessage =
  | { name: typeof MessageSocketServerEvent; payload: ServerEvent };

const receivedMessages: readonly RtCandidate[] = [
  {
    name: MessageSocketServerEvent,
    matchers: [],
    fallback: false,
    check: (payload: unknown): void => {
      validateServerEvent(payload, MessageSocketServerEvent);
    },
  },
];

/**
 * decodeReceivedMessage works out which incoming message data is and checks
 * it. It throws UnknownMessageError when nothing matches and
 * AmbiguousMessageError when several messages match.
 */
export function decodeReceivedMessage(data: string): ReceivedMessage {
  const [name, payload] = rtDecodeMessage(data, receivedMessages);

  return { name, payload } as ReceivedMessage;
}

/** Handler receives incoming messages. Implement only the methods you need. */
export interface Handler {
  /**
   * Payload: ServerEvent.
   */
  handleSocketServerEvent?(payload: ServerEvent): void | Promise<void>;
  /**
   * handleUnknownMessage gets every message that matched nothing, with the
   * reason. Without it, Client.receive throws the error.
   */
  handleUnknownMessage?(
    data: string,
    error: UnknownMessageError | AmbiguousMessageError,
  ): void | Promise<void>;
}

/** dispatch passes message to the handler method for its name. */
export async function dispatch(
  handler: Handler,
  message: ReceivedMessage,
): Promise<void> {
  switch (message.name) {
    case MessageSocketServerEvent:
      await handler.handleSocketServerEvent?.(message.payload);

      return;
  }
}

/** Transport carries text frames. A browser WebSocket fits it as it is. */
export interface Transport {
  send(data: string): void | Promise<void>;
  close(): void;
}

/** Client sends and receives this API's messages over a transport. */
export class Client {
  private readonly transport: Transport;

  constructor(transport: Transport) {
    this.transport = transport;
  }

  /** close closes the transport. */
  close(): void {
    this.transport.close();
  }

  /**
   * sendMessage checks payload and sends it as a MessageSocketMessageSend message.
   */
  async sendMessage(payload: MessageSend): Promise<void> {
    validateMessageSend(payload, MessageSocketMessageSend);
    await this.transport.send(JSON.stringify(payload));
  }

  /**
   * receive decodes one incoming frame and passes it to handler. A frame that
   * matches nothing goes to handler.handleUnknownMessage, or is thrown when
   * the handler has no such method.
   */
  async receive(data: string, handler: Handler): Promise<void> {
    let message: ReceivedMessage;

    try {
      message = decodeReceivedMessage(data);
    } catch (err) {
      const isUnmatched =
        err instanceof UnknownMessageError ||
        err instanceof AmbiguousMessageError;
      if (!isUnmatched || handler.handleUnknownMessage === undefined) {
        throw err;
      }

      await handler.handleUnknownMessage(data, err);

      return;
    }

    await dispatch(handler, message);
  }
}

// Runtime helpers used by the code above.

function rtFail(path: string, reason: string): never {
  throw new ValidationError(path, reason);
}

function rtObject(value: unknown, path: string): Record<string, unknown> {
  if (typeof value !== "object" || value === null || Array.isArray(value)) {
    rtFail(path, "not an object");
  }

  return value as Record<string, unknown>;
}

function rtArray(value: unknown, path: string): readonly unknown[] {
  if (!Array.isArray(value)) {
    rtFail(path, "not an array");
  }

  return value;
}

function rtString(value: unknown, path: string): string {
  if (typeof value !== "string") {
    rtFail(path, "not a string");
  }

  return value;
}

function rtInteger(value: unknown, path: string): number {
  if (typeof value !== "number" || !Number.isInteger(value)) {
    rtFail(path, "not an integer");
  }

  return value;
}

function rtBoolean(value: unknown, path: string): boolean {
  if (typeof value !== "boolean") {
    rtFail(path, "not a boolean");
  }

  return value;
}

const rtDateTimePattern = new RegExp(
  "^\\d{4}-\\d{2}-\\d{2}[Tt]\\d{2}:\\d{2}:\\d{2}(\\.\\d+)?([Zz]|[+-]\\d{2}:\\d{2})$",
);

function rtDateTime(value: unknown, path: string): string {
  const text = rtString(value, path);
  if (!rtDateTimePattern.test(text) || Number.isNaN(Date.parse(text))) {
    rtFail(path, "not an RFC 3339 date-time");
  }

  return text;
}

function rtRequire(
  path: string,
  object: Record<string, unknown>,
  names: readonly string[],
): void {
  for (const name of names) {
    if (!Object.prototype.hasOwnProperty.call(object, name)) {
      rtFail(path, `missing required property "${name}"`);
    }
  }
}

function rtKnownKeys(
  path: string,
  object: Record<string, unknown>,
  names: readonly string[],
): void {
  for (const key of Object.keys(object)) {
    if (!names.includes(key)) {
      rtFail(path, `unknown property "${key}"`);
    }
  }
}

function rtCanonical(value: unknown): string {
  if (Array.isArray(value)) {
    return `[${value.map(rtCanonical).join(",")}]`;
  }

  if (typeof value === "object" && value !== null) {
    const record = value as Record<string, unknown>;
    const members = Object.keys(record)
      .sort()
      .map((key) => `${JSON.stringify(key)}:${rtCanonical(record[key])}`);

    return `{${members.join(",")}}`;
  }

  return JSON.stringify(value);
}

function rtConst(path: string, value: unknown, expected: unknown): void {
  if (rtCanonical(value) !== rtCanonical(expected)) {
    rtFail(path, `want ${JSON.stringify(expected)}`);
  }
}

function rtEnum(
  path: string,
  value: unknown,
  values: readonly unknown[],
): void {
  if (!values.includes(value)) {
    rtFail(path, `unknown value ${JSON.stringify(value)}`);
  }
}

function rtMinLength(path: string, value: string, limit: number): void {
  if (Array.from(value).length < limit) {
    rtFail(path, `shorter than ${limit} characters`);
  }
}

function rtMinimum(path: string, value: number, limit: number): void {
  if (value < limit) {
    rtFail(path, `less than ${limit}`);
  }
}

function rtMinItems(path: string, count: number, limit: number): void {
  if (count < limit) {
    rtFail(path, `fewer than ${limit} items`);
  }
}

function rtDiscriminator(
  path: string,
  object: Record<string, unknown>,
  property: string,
): string {
  if (!Object.prototype.hasOwnProperty.call(object, property)) {
    rtFail(path, `missing discriminator "${property}"`);
  }

  const value = object[property];
  if (typeof value === "string") {
    return value;
  }

  return JSON.stringify(value);
}

function rtPointer(document: unknown, pointer: string): [unknown, boolean] {
  if (pointer === "") {
    return [document, true];
  }

  let current = document;

  for (const raw of pointer.slice(1).split("/")) {
    const token = raw.split("~1").join("/").split("~0").join("~");

    if (Array.isArray(current)) {
      const index = Number(token);
      if (!Number.isInteger(index) || index < 0 || index >= current.length) {
        return [undefined, false];
      }

      current = current[index];

      continue;
    }

    if (typeof current !== "object" || current === null) {
      return [undefined, false];
    }

    const record = current as Record<string, unknown>;
    if (!Object.prototype.hasOwnProperty.call(record, token)) {
      return [undefined, false];
    }

    current = record[token];
  }

  return [current, true];
}

interface RtMatcher {
  readonly pointer: string;
  readonly value: unknown;
}

interface RtCandidate {
  readonly name: string;
  readonly matchers: readonly RtMatcher[];
  readonly fallback: boolean;
  readonly check: (payload: unknown) => void;
}

function rtMatchesAll(document: unknown, matchers: readonly RtMatcher[]): boolean {
  return matchers.every((matcher) => {
    const [actual, found] = rtPointer(document, matcher.pointer);

    return found && rtCanonical(actual) === rtCanonical(matcher.value);
  });
}

function rtDecodeOne(
  document: unknown,
  candidates: readonly RtCandidate[],
): string {
  const reasons: string[] = [];
  const matched: string[] = [];

  for (const candidate of candidates) {
    try {
      candidate.check(document);
      matched.push(candidate.name);
    } catch (err) {
      if (!(err instanceof ValidationError)) {
        throw err;
      }

      reasons.push(`${candidate.name}: ${err.message}`);
    }
  }

  if (matched.length > 1) {
    throw new AmbiguousMessageError(matched);
  }

  const name = matched[0];
  if (name === undefined) {
    throw new UnknownMessageError(reasons);
  }

  return name;
}

function rtDecodeMessage(
  data: string,
  candidates: readonly RtCandidate[],
): [string, unknown] {
  let document: unknown;
  try {
    document = JSON.parse(data) as unknown;
  } catch (err) {
    throw new UnknownMessageError([`message is not JSON: ${String(err)}`]);
  }

  const pinned = candidates.filter(
    (candidate) =>
      candidate.matchers.length > 0 &&
      rtMatchesAll(document, candidate.matchers),
  );
  if (pinned.length > 0) {
    return [rtDecodeOne(document, pinned), document];
  }

  const unpinned = candidates.filter(
    (candidate) => candidate.matchers.length === 0 && !candidate.fallback,
  );
  const fallbacks = candidates.filter((candidate) => candidate.fallback);

  try {
    return [rtDecodeOne(document, unpinned), document];
  } catch (err) {
    if (!(err instanceof UnknownMessageError) || fallbacks.length === 0) {
      throw err;
    }
  }

  return [rtDecodeOne(document, fallbacks), document];
}
